from enum import Enum
from typing import Annotated, TypeAlias

from ...core import open_enum_validator


class Provenance2(str, Enum):
    """The origin of the audio track.

    Option descriptions:
     * ``ai_generated`` - The audio track is generated by AI.
     * ``user_uploaded`` - The audio track is uploaded by a user.
     * ``user_uploaded_and_ai_generated`` - The audio track is uploaded by a user and contains AI content."""

    AI_GENERATED = "ai_generated"
    USER_UPLOADED = "user_uploaded"
    USER_UPLOADED_AND_AI_GENERATED = "user_uploaded_and_ai_generated"

    __str__ = str.__str__


Provenance2OrStr: TypeAlias = Annotated[Provenance2 | str, open_enum_validator(Provenance2)]
